### Step 4: Implement complementary_terms

33-term Fourier series for ERA-based sidereal time. Returns correction in **degrees**.

```rust
fn complementary_terms(tt: f64) -> f64 {
    let delm = nutation::planetary_args_iau2000(tt);
    let mut dadd = -0.87 * delm[4].sin() * tt;

    for i in 0..33 {
        let darg: f64 = (0..14).map(|j| f64::from(STFARG[i][j]) * delm[j]).sum();
        dadd += STCF[i][0] * darg.sin() + STCF[i][1] * darg.cos();
    }

    dadd / (3600.0 * 1_000_000.0)
}
```

### Step 5: Implement gmst_iau1976

GMST via IAU 1976 polynomial (Aoki et al. 1982). Returns sidereal **seconds**.
`tu` is UT1 centuries from J2000. IAU 1976 does NOT use TT for the polynomial.

```rust
fn gmst_iau1976(jd0: f64, secs: f64) -> f64 {
    let tu = (jd0 - J2000) / 36525.0;
    let gmst_0h = ((-6.2e-6 * tu + 9.3104e-2) * tu + 8640184.812866) * tu + 24110.54841;
    let msday =
        1.0 + ((-1.86e-5 * tu + 0.186208) * tu + 8640184.812866) / (86400.0 * 36525.0);
    gmst_0h + msday * secs
}
```

### Step 6: Implement gmst_iau2006

GMST via IAU 2006 polynomial (Capitaine et al. 2003). Returns sidereal **seconds**.
Uses TT at UT midnight for the polynomial (distinct from IAU 1976 which uses UT1).

```rust
fn gmst_iau2006(jd0: f64, secs: f64, tu: f64, config: &EphemerisConfig) -> f64 {
    let tt = (jd0 + calc_deltat(jd0, config) - J2000) / 36525.0;

    let gmst_0h = (((-0.000000002454 * tt - 0.00000199708) * tt - 0.0000002926) * tt
        + 0.092772110)
        * tt * tt
        + 307.4771013 * (tt - tu)
        + 8640184.79447825 * tu
        + 24110.5493771;

    let msday = 1.0
        + ((((-0.000000012270 * tt - 0.00000798832) * tt - 0.0000008778) * tt
            + 0.185544220) * tt
            + 8640184.79447825)
            / (86400.0 * 36525.0);

    gmst_0h + msday * secs
}
```

### Step 7: Implement gmst_era

GMST via ERA + polynomial correction + complementary terms (IERS 2010 / Longterm in-range).
Returns sidereal **seconds**. Uses full tjd for TT (not midnight).

```rust
fn gmst_era(tjd_ut: f64, config: &EphemerisConfig) -> f64 {
    let jdrel = tjd_ut - J2000;
    let tt = (tjd_ut + calc_deltat(tjd_ut, config) - J2000) / 36525.0;

    // ERA (degrees)
    let mut gmst = normalize_degrees((0.7790572732640 + 1.00273781191135448 * jdrel) * 360.0);

    // Polynomial correction: arcsec → degrees
    gmst += (0.014506
        + tt * (4612.156534
        + tt * (1.3915817
        + tt * (-0.00000044
        + tt * (-0.000029956
        + tt * -0.0000000368)))))
        / 3600.0;

    // Complementary terms (degrees)
    gmst = normalize_degrees(gmst + complementary_terms(tt));

    // degrees → sidereal seconds
    gmst / 15.0 * 3600.0
}
```

### Step 8: Implement sidtime_long_term

Long-term model (Simon et al. 1994) for dates outside [1850, 2050]. Returns **hours** [0, 24).
Uses mean Earth longitude → ecliptic→equatorial→precess→ecliptic pipeline.

```rust
fn sidtime_long_term(
    tjd_ut: f64,
    eps: f64,  // true obliquity in radians (0.0 = compute internally)
    nut: f64,  // dpsi in radians (0.0 = compute internally)
    config: &EphemerisConfig,
) -> f64 {
    let flags = CalcFlags::empty();
    let models = &config.astro_models;
    let tjd_et = tjd_ut + calc_deltat(tjd_ut, config);
    let t = (tjd_et - J2000) / 365250.0;  // Julian millennia
    let dlt = AUNIT / CLIGHT / 86400.0;

    // Mean Earth longitude (degrees, J2000 ecliptic)
    let dlon = 100.46645683
        + (1295977422.83429 * t - 2.04411 * t * t - 0.00523 * t * t * t) / 3600.0;
    let dlon = normalize_degrees(dlon - dlt * 360.0 / 365.2425);

    // Cartesian on unit sphere
    let mut xs = polar_to_cartesian([dlon * DEGTORAD, 0.0, 1.0]);

    // Ecliptic → equatorial J2000
    let eps_j2000 = obliquity::obliquity(J2000 + calc_deltat(J2000, config), flags, models);
    xs = rotate_x(xs, -eps_j2000.eps);

    // Precess J2000 → date
    precession::precess(&mut xs, tjd_et, flags, models, PrecessionDirection::J2000ToDate);

    // Obliquity and nutation of date (for equatorial→ecliptic rotation)
    let eps_date = obliquity::obliquity(tjd_et, flags, models);
    let nut_date = nutation::nutation(tjd_et, flags, models);

    // Equatorial → ecliptic of date
    xs = rotate_x(xs, eps_date.eps);
    let mut pol = cartesian_to_polar(xs);
    pol[0] *= RADTODEG;  // longitude in degrees

    // UT fraction → hour angle (degrees)
    let dhour = ((tjd_ut - 0.5) % 1.0) * 360.0;

    // EoE in degrees: dpsi_deg * cos(eps_true_rad)
    if eps == 0.0 {
        let eps_true = eps_date.eps + nut_date.deps;
        pol[0] += (nut_date.dpsi * RADTODEG) * eps_true.cos();
    } else {
        pol[0] += (nut * RADTODEG) * eps.cos();
    }

    normalize_degrees(pol[0] + dhour) / 15.0
}
```

### Step 9: Implement sidereal_time0 (main dispatcher)

Public function. Takes eps (true obliquity) and nut (dpsi) in **radians**. Returns hours [0, 24).

```rust
pub fn sidereal_time0(
    tjd_ut: f64,
    eps: f64,
    nut: f64,
    config: &EphemerisConfig,
) -> f64 {
    let sidt_model = config.astro_models.sidereal_time;

    // Long-term model: outside [1850, 2050] use sidtime_long_term directly
    if sidt_model == SiderealTimeModel::Longterm {
        if tjd_ut <= SIDT_LTERM_T0 || tjd_ut >= SIDT_LTERM_T1 {
            let mut gmst = sidtime_long_term(tjd_ut, eps, nut, config);
            if tjd_ut <= SIDT_LTERM_T0 {
                gmst -= SIDT_LTERM_OFS0;
            } else {
                gmst -= SIDT_LTERM_OFS1;
            }
            if gmst >= 24.0 { gmst -= 24.0; }
            if gmst < 0.0 { gmst += 24.0; }
            return gmst;
        }
        // else: fall through to ERA path (1850–2050 range)
    }

    // Compute jd0 (UT midnight) and secs (UT seconds since midnight)
    let mut jd0 = tjd_ut.floor();
    let mut secs = tjd_ut - jd0;
    if secs < 0.5 {
        jd0 -= 0.5;
        secs += 0.5;
    } else {
        jd0 += 0.5;
        secs -= 0.5;
    }
    secs *= 86400.0;
    let tu = (jd0 - J2000) / 36525.0;

    // GMST in sidereal seconds (model-dependent)
    let mut gmst = match sidt_model {
        SiderealTimeModel::IersConv2010 | SiderealTimeModel::Longterm => {
            gmst_era(tjd_ut, config)
        }
        SiderealTimeModel::IAU2006 => gmst_iau2006(jd0, secs, tu, config),
        SiderealTimeModel::IAU1976 => gmst_iau1976(jd0, secs),
    };

    // Equation of the Equinoxes (sidereal seconds)
    // C: eqeq = 240.0 * nut_deg * cos(eps_deg * DEGTORAD)
    // Rust: eps/nut in radians, so convert nut to degrees for the 240 factor
    let eqeq = 240.0 * (nut * RADTODEG) * eps.cos();
    gmst += eqeq;

    // Normalize to [0, 86400) seconds, convert to hours
    gmst -= 86400.0 * (gmst / 86400.0).floor();
    gmst /= 3600.0;

    // Boundary sanitization (considerations §4)
    if gmst >= 24.0 { gmst = 0.0; }

    gmst
}
```

### Step 10: Implement sidereal_time (convenience wrapper)

Public function. Computes obliquity, nutation, and delta-T internally. Returns hours [0, 24).

```rust
pub fn sidereal_time(tjd_ut: f64, config: &EphemerisConfig) -> f64 {
    let flags = CalcFlags::empty();
    let models = &config.astro_models;

    // UT1 → TT (considerations §1: must use TT for obliquity/nutation)
    let tjd_et = tjd_ut + calc_deltat(tjd_ut, config);

    // Mean obliquity + nutation
    let eps = obliquity::obliquity(tjd_et, flags, models);
    let nut = nutation::nutation(tjd_et, flags, models);

    // True obliquity = mean + deps
    let eps_true = eps.eps + nut.deps;

    sidereal_time0(tjd_ut, eps_true, nut.dpsi, config)
}
```

